import "server-only";
import { neon } from "@neondatabase/serverless";

if (!process.env.DATABASE_URL) {
  throw new Error("DATABASE_URL is missing from .env.local");
}

/**
 * Neon HTTP query function — a tagged template literal for parameterized queries.
 *
 * HTTP mode is true serverless (no persistent connection) and fully
 * Edge-compatible (Vercel Edge, Cloudflare Workers). Values interpolated with
 * ${} are sent as bound parameters, so they are safe from SQL injection.
 *
 * Example:
 *   const rows = await sql`SELECT * FROM users WHERE id = ${userId}`;
 *
 * For interactive, multi-statement transactions, use an ORM adapter
 * (Prisma / Drizzle) or Neon's batch API: sql.transaction([...]).
 * Those manage their own WebSocket pool — see infra/neon/adapter.ts.
 */
export const sql = neon(process.env.DATABASE_URL);

