import "server-only";

import { sql } from "./client";

// NOTE: `server-only` (not `"use server"`). These are plain server-side
// helpers meant to be called from Server Components, Route Handlers, and your
// own Server Actions — NOT exposed directly to the client as RPC endpoints.
// Exposing a raw-SQL executor as a Server Action would let the browser run
// arbitrary queries.

/**
 * Typed wrapper around the Neon HTTP tagged template literal.
 * Values interpolated with ${} are bound as query parameters — safe from
 * SQL injection.
 *
 * Example:
 *   const users = await query<User>`SELECT * FROM users WHERE id = ${userId}`;
 */
export async function query<T>(
  strings: TemplateStringsArray,
  ...values: unknown[]
): Promise<T[]> {
  return sql(strings, ...values) as Promise<T[]>;
}

// SQL parameters cannot bind an identifier (a table or column name), so a
// dynamic table name must be validated against a fixed allowlist before it is
// interpolated into the query text. Add your real tables here.
const ALLOWED_TABLES = new Set<string>([
  // "users",
  // "posts",
]);

export async function getRows<T>(table: string): Promise<T[]> {
  if (!ALLOWED_TABLES.has(table)) {
    throw new Error(`Table "${table}" is not in the allowlist.`);
  }
  // Safe: `table` is one of a fixed, code-controlled set of identifiers.
  const rows = await sql.query(`SELECT * FROM ${table} LIMIT 100`);
  return rows as T[];
}
